/*
 * A037313  Numbers whose base-3 and base-8 expansions have the same digit
 *          sum.
 * https://oeis.org/A037313
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 20, u16 n <= 48, u32 n <= 48, u64 n <= 48, u128 n <= 48,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: Numbers whose base-3 and base-8 expansions have the same digit sum */
/* The sequence is generated by brute‑force search; the n‑th term is found by
   scanning successive integers and collecting those whose digit sums in base
   3 and base 8 coincide. */

#include <stdlib.h>
#include <stddef.h>

/* returns the sum of the digits of x in the given base (base <= 10) */
static unsigned int digit_sum_base(seq_t x, int base)
{
    unsigned int sum = 0;
    while (x != (seq_t)0) {
        sum += (unsigned int)(x % base);
        x /= base;
    }
    return sum;
}

/* ensures that an array has at least 'need' elements */
static void ensure_capacity(size_t *cap, seq_t **arr, size_t need)
{
    if (*cap < need) {
        size_t new_cap = (*cap == 0) ? 8 : (*cap << 1);
        while (new_cap < need) new_cap <<= 1;
        seq_t *tmp = (seq_t *)realloc(*arr, new_cap * sizeof(seq_t));
        *arr = tmp;
        *cap = new_cap;
    }
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;          /* offset 1; caller may never ask for 0 */

    static seq_t *cache      = NULL;      /* stored sequence values      */
    static size_t cache_cap  = 0;         /* current allocated capacity  */
    static size_t cache_len  = 0;         /* number of terms cached      */
    static seq_t next_candidate = (seq_t)1; /* next integer to test          */

    /* generate terms until we have at least n of them */
    while (cache_len < (size_t)n) {
        unsigned int s3 = digit_sum_base(next_candidate, 3);
        unsigned int s8 = digit_sum_base(next_candidate, 8);
        if (s3 == s8) {
            ensure_capacity(&cache_cap, &cache, cache_len + 1);
            cache[cache_len++] = next_candidate;
        }
        next_candidate++;                  /* move to the next integer   */
    }

    return cache[n - 1];                    /* 1‑based indexing           */
}
